import sys
input = sys.stdin.readline
output = sys.stdout.write

def find(x):
	t = x
	while fa[x] != x:
		x = fa[x]
	while t != x:
		(fa[t], t) = (x, fa[t])
	return x

def union(son, father):
	x = find(son)
	y = find(father)
	fa[x] = y

def f(num):
	ans = 0
	while num > 0:
		ans += num % 10
		num //= 10
	return ans
n = int(input())
for _ in range(n):
	(m, q) = list(map(int, input().split()))
	fa = list(range(m + 1))
	if fa[0] == 9999999:
		print(0)
		break
	a = list(map(int, input().split()))
	for _ in range(q):
		t = list(map(int, input().split()))
		if t[0] == 1:
			(l, r) = (t[1], t[2])
			l -= 1
			l = fa[l]
			while l < r:
				a[l] = f(a[l])
				if a[l] < 10:
					union(l, l + 1)
				l = fa[l + 1]
		else:
			print(a[t[1] - 1])
